import{_ as n,o as r,c as a,ah as t}from"./chunks/framework.Bja9t6Wf.js";const f=JSON.parse('{"title":"Update: Differenzanalyse – Gutachten Hoeres vs. Projekt-Recherche","description":"","frontmatter":{"title":"Update: Differenzanalyse – Gutachten Hoeres vs. Projekt-Recherche","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-differenzanalyse-gutachten.md","filePath":"logbuch/2026-02-27-differenzanalyse-gutachten.md"}'),s={name:"logbuch/2026-02-27-differenzanalyse-gutachten.md"};function i(o,e,h,l,d,u){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="update-differenzanalyse-–-gutachten-hoeres-vs-projekt-recherche" tabindex="-1">Update: Differenzanalyse – Gutachten Hoeres vs. Projekt-Recherche <a class="header-anchor" href="#update-differenzanalyse-–-gutachten-hoeres-vs-projekt-recherche" aria-label="Permalink to &quot;Update: Differenzanalyse – Gutachten Hoeres vs. Projekt-Recherche&quot;">​</a></h1><p><strong>27. Februar 2026</strong></p><p>Heute haben wir einen tiefgehenden Vergleich zwischen dem wissenschaftlichen Gutachten von Prof. Dr. Peter Hoeres (2022) und unseren eigenen Rechercheergebnissen für das Projekt „Dokfilm“ abgeschlossen. Die Ergebnisse sind ebenso aufschlussreich wie motivierend für unsere weitere Drehbucharbeit.</p><h2 id="kernpunkte-der-analyse" tabindex="-1">Kernpunkte der Analyse <a class="header-anchor" href="#kernpunkte-der-analyse" aria-label="Permalink to &quot;Kernpunkte der Analyse&quot;">​</a></h2><p>Der Vergleich macht deutlich, wo die Bruchstellen zwischen akademischer Geschichtsschreibung und unserer narrativen Annäherung liegen:</p><ol><li><strong>Die Duisburg-Frage:</strong> Während das Gutachten die Übernahme von Alsberg bereits 1936 verortet und als „vergleichsweise fair“ einstuft, fokussiert unsere Recherche auf den 1. Mai 1938 und die systemische Gewalt, die hinter jedem Arisierungs-Vertrag stand.</li><li><strong>Moral vs. Ökonomie:</strong> Hoeres analysiert Horten als opportunistischen Geschäftsmann. Wir rücken das Schicksal der Opfer – wie Emma und Alfred Alsberg – ins Zentrum und stellen die Frage nach der moralischen Mitschuld eines Profiteurs.</li><li><strong>Die Johannisthal-Beteiligung:</strong> Ein für uns neuer und belastender Aspekt aus dem Gutachten ist der Nachweis von Hortens Beteiligung an der Rüstungsproduktion und dem Einsatz von Zwangsarbeitern in Berlin-Johannisthal ab 1943. Dies liefert uns ein starkes neues Motiv für die Mockumentary.</li></ol><h2 id="download-der-analyse" tabindex="-1">Download der Analyse <a class="header-anchor" href="#download-der-analyse" aria-label="Permalink to &quot;Download der Analyse&quot;">​</a></h2><p>Die detaillierte Gegenüberstellung der Argumente und Fakten haben wir in einem Dokument zusammengefasst:</p><p>👉 <strong><a href="/Differenzanalyse_Horten.pdf">Differenzanalyse_Horten.pdf</a></strong></p><h2 id="fazit-fur-das-projekt" tabindex="-1">Fazit für das Projekt <a class="header-anchor" href="#fazit-fur-das-projekt" aria-label="Permalink to &quot;Fazit für das Projekt&quot;">​</a></h2><p>Die Differenzen liegen oft weniger in den nackten Zahlen als in der <strong>Perspektive</strong>. Das Gutachten bietet eine wertvolle faktische Basis, die wir nutzen werden, um die „weiße Weste“ des Kaufhauskönigs noch präziser zu hinterfragen. Gerade die Zwangsarbeit in Johannisthal ist ein Thema, das in der öffentlichen Wahrnehmung Hortens bisher kaum eine Rolle spielt.</p><p><em>Euer Team von Dokfilm</em></p>',12)])])}const g=n(s,[["render",i]]);export{f as __pageData,g as default};
